import { parsePackageJson, type FileSystem, type Package } from '@servicenow/sdk-build-core'
import { findRoot } from './fshelpers'
import { exec } from 'child_process'

export function getInstalledPackageInfo(packageDir: string, fs: FileSystem) {
    try {
        const packageJson = parsePackageJson(findRoot(packageDir, fs), fs)
        return { version: packageJson.version, name: packageJson.name }
    } catch {
        return {} as unknown as Package
    }
}

export async function getLatestNpmPackageVersion(npmPackage: string): Promise<string> {
    const registryUrl = process.env['NODE_ENV'] === 'test' ? 'http://fake_registry.com' : await getRegistryUrl()

    const response = await fetch(`${registryUrl}/${npmPackage}`)

    if (!response.ok) {
        return ''
    }

    const body = await response.json()
    const latestVersion = body?.['dist-tags']?.latest
    return latestVersion
}

async function getRegistryUrl() {
    const registryUrl = (await new Promise((resolve, reject) => {
        const npmCommand = 'npm config get registry -ws=false -iwr'
        exec(npmCommand, (err, stdout) => {
            if (err) {
                reject(err)
            } else {
                resolve(stdout)
            }
        })
    })) as string

    const trimmedRegistryUrl = registryUrl && registryUrl.trim()
    if (!trimmedRegistryUrl) {
        throw new Error('Could not find npm registry')
    }
    return trimmedRegistryUrl
}
